#include "../src/domain/healthcare.hpp"
#include <cassert>
int main(){carebridge::Patient p("p1","Synthetic Patient","p@example.test");carebridge::Doctor d("d1","Demo Doctor","d@example.test","General Practice");assert(p.kind()=="patient"&&d.kind()=="doctor");carebridge::Appointment a("a1","p1","d1");a.transition("approved");a.transition("completed");bool failed=false;try{a.transition("booked");}catch(const std::invalid_argument&){failed=true;}assert(failed);carebridge::LaboratoryOrder o("l1","p1","d1","haematology","CBC");failed=false;try{o.begin("tech1");}catch(const std::runtime_error&){failed=true;}assert(failed);o.assign("tech1");o.begin("tech1");o.complete("tech1");assert(o.status()=="Completed");carebridge::Consent c={"p1","d1","vitals","active"};assert(c.permits("p1","d1","vitals"));carebridge::HealthcareSystem system;assert(system.indexRecord(7)&&system.hasRecord(7));assert(system.enqueueLab(3));int id=0;assert(system.nextLab(id)&&id==3);}
